31	export const isVirtualId = (id: string) => id.startsWith("vv_");
32	
33	// Incremented for every explicit tree transition so a slower link resolution
34	// cannot select a tree after a newer selection or disconnect has won.
35	let treeRequestVersion = 0;
36	
37	interface DatabaseMetaData {
38	  id?: string;
39	  name?: string;
40	  createdAt?: string;
41	  lastOpened?: string;
42	  hasLayout?: boolean;
43	  overlapCount?: number;
44	}
45	
46	/** One hop in the tree-in-tree breadcrumb: a tree the user navigated *from*. */
47	interface TreeNavEntry {
48	  id: string;
49	  name: string;
50	}
51	
52	interface DatabaseState {
53	  trees: Tree[];
54	  virtualViews: Tree[];
55	  selectedTree: Tree | undefined;
56	  metadata: DatabaseMetaData;
57	  relationTypes: RelationTypeDB[];
58	  isReady: boolean;
59	  // Ancestor chain for the tree-in-tree feature: the trees the user came from
60	  // when following member→tree links. Empty when viewing a top-level tree.
61	  treeNavStack: TreeNavEntry[];
62	
63	  loadTrees: () => Promise<void>;
64	  openTreeById: (treeId: string) => Promise<Tree>;
65	  openTreeAndLocateMember: (treeId: string, memberId: string) => Promise<void>;
66	  unlockPublicTree: (treeId: string, password: string) => Promise<Tree>;
67	  createTree: (name: string, options?: { select?: boolean }) => Promise<Tree>;
68	  openLinkedTree: (
69	    treeId: string,
70	    focusMemberId?: string | null,
71	  ) => Promise<void>;
72	  createLinkedSubtree: (memberId: string, name: string) => Promise<Tree>;
73	  linkExistingTree: (
74	    memberId: string,
75	    body: {
76	      linked_tree_id: string;
77	      mode: "existing" | "create";
78	      counterpart_member_id?: string | null;
79	      field_choices?: Partial<Record<string, MergeFieldChoice>>;
80	    },
81	  ) => Promise<Tree>;
82	  navigateToTreeStack: (index: number) => Promise<void>;
83	  renameTree: (tree: Tree, name: string) => Promise<void>;
84	  updateTree: (tree: Tree) => void;
85	  deleteTree: (tree: Tree) => Promise<void>;
86	  mergeTrees: (
87	    name: string,
88	    sourceA: string,
89	    sourceB?: string,
90	    resolutions?: MergeResolution[],
91	  ) => Promise<Tree>;
92	  extractSubtree: (payload: SubtreeExtractPayload) => Promise<Tree>;
93	  extractSubtreePreview: (
94	    payload: Omit<SubtreeExtractPayload, "name">,
95	  ) => Promise<SubtreeExtractPreview>;
96	  fetchTreeMembers: (treeId: string) => Promise<Member[]>;
97	  createVirtualView: (name: string, sourceTreeIds: string[]) => Promise<Tree>;
98	  renameVirtualView: (view: Tree, name: string) => Promise<void>;
99	  updateVirtualViewSources: (
100	    view: Tree,
101	    sourceTreeIds: string[],
102	  ) => Promise<void>;
103	  deleteVirtualView: (view: Tree) => Promise<void>;
104	  recomputeMatches: (
105	    view: Tree,
106	  ) => Promise<{ groupCount: number; mergedMemberCount: number }>;
107	  selectTree: (tree: Tree | undefined) => Promise<void>;
108	  connect: (tree: Tree) => Promise<void>;
109	  disconnect: () => Promise<void>;
110	  disconnectPublicTree: () => Promise<void>;
111	  refreshMetadata: (treeId?: string) => Promise<void>;
112	  refreshRelationTypes: () => Promise<void>;
113	}
114	
115	const clearDataStores = () => {
116	  useMemberStore.getState().clear();
117	  useGalleryStore.getState().clear();
118	  useEventStore.getState().clear();
119	  useStoryStore.getState().clear();
120	  clearTaskStore();
121	  useDocumentStore.getState().clear();
122	  useActivityStore.getState().clear();
123	  useStatisticsStore.getState().clear();
124	  useQualityReportStore.getState().clear();
125	  useStorageStore.getState().clear();
126	};
