128	export const useTreeStore = create<DatabaseState>((set, get) => ({
129	  trees: [],
130	  virtualViews: [],
131	  selectedTree: undefined,
132	  metadata: {},
133	  relationTypes: [],
134	  isReady: false,
135	  treeNavStack: [],
136	
137	  loadTrees: async () => {
138	    const [trees, virtualViews] = await Promise.all([
139	      api.get<Tree[]>("/trees"),
140	      hasFeature("virtual_views")
141	        ? TreeService.listVirtualViews().catch(() => [] as Tree[])
142	        : Promise.resolve([] as Tree[]),
143	    ]);
144	    set({ trees, virtualViews });
145	    // Drop a stale selection that no longer exists / is no longer accessible.
146	    const selected = get().selectedTree;
147	    const allItems = [...trees, ...virtualViews];
148	    if (!selected) return;
149	    const freshSelected = allItems.find((t) => t.id === selected.id);
150	    if (freshSelected) {
151	      set({ selectedTree: freshSelected });
152	      return;
153	    }
154	    await get().disconnect();
155	    // Land on the most recently used remaining tree/view (the API sorts by
156	    // last_opened — same rule as startup in App.tsx) instead of leaving a
157	    // blank canvas. Best effort: if it fails to open, stay disconnected.
158	    const next = allItems[0];
159	    if (next) {
160	      await get()
161	        .selectTree(next)
162	        .catch(() => {});
163	    }
164	  },
165	
166	  // Resolve a tree before selecting it. This keeps link routing, including
167	  // public-tree links that are absent from a user's normal tree list, inside
168	  // the tree domain rather than making view components call the API directly.
169	  openTreeById: async (treeId: string) => {
170	    const requestVersion = ++treeRequestVersion;
171	    const tree = await api.get<Tree>(`/trees/${treeId}`);
172	    if (requestVersion !== treeRequestVersion) return tree;
173	    await get().selectTree(tree);
174	    return tree;
175	  },
176	
177	  openTreeAndLocateMember: async (treeId: string, memberId: string) => {
178	    const tree = await get().openTreeById(treeId);
179	    if (!isActiveTree(tree.id)) return;
180	    useMemberSheetStore.getState().setOpenSheet(tree.id, {
181	      memberId,
182	      tab: "identity",
183	      mode: "view",
184	    });
185	    // Set after the tree transition: connect() clears the member store, and
186	    // the canvas consumes this once the selected member has finished loading.
187	    useMemberStore.getState().setPendingLocateMemberId(memberId);
188	  },
189	
190	  unlockPublicTree: async (treeId: string, password: string) => {
191	    const { token } = await TreeSharingService.unlockPublicTree(
192	      treeId,
193	      password,
194	    );
195	    setPublicTreeToken(token);
196	    return get().openTreeById(treeId);
197	  },
198	
199	  createTree: async (name: string, options?: { select?: boolean }) => {
200	    const tree = await api.post<Tree>("/trees", { name });
201	    set((s) => ({ trees: [tree, ...s.trees] }));
202	    // `select: false` lets callers create a tree without switching to it — used
203	    // by the tree-in-tree "create & link" action so the current edit context is
204	    // preserved.
205	    if (options?.select !== false) {
206	      await get().selectTree(tree);
207	    }
208	    return tree;
209	  },
210	
211	  // Follow a member→tree link: remember where we came from (breadcrumb), verify
212	  // the target is accessible, then switch to it. Throws if the linked tree is
213	  // missing or the user has no access, so callers can surface a message.
214	  // When the link carries a counterpart member (the bridge person's row in the
215	  // target tree), the canvas centers on it after the switch.
216	  openLinkedTree: async (treeId: string, focusMemberId?: string | null) => {
217	    const current = get().selectedTree;
218	    if (!current || current.id === treeId) return;
219	    const target = await api.get<Tree>(`/trees/${treeId}`);
220	    // Following a back-link to where we just came from behaves like "back":
221	    // pop the breadcrumb instead of growing it (A → B → A stays two levels).
222	    const stack = get().treeNavStack;
223	    const last = stack[stack.length - 1];
224	    if (last && last.id === treeId) {
225	      set({ treeNavStack: stack.slice(0, -1) });
226	    } else {
227	      set({
228	        treeNavStack: [...stack, { id: current.id, name: current.name }],
229	      });
230	    }
231	    await get().connect(target);
232	    if (focusMemberId) {
233	      // Set after connect: the tree switch clears the member store, and the
234	      // canvas consumes this once the counterpart is present in `members`.
235	      useMemberStore.getState().setPendingLocateMemberId(focusMemberId);
236	    }
237	  },
238	
239	  // Tree-in-tree "create & link": one atomic backend call creates the new
240	  // tree, seeds it with a copy of the member (the bridge person) and links
241	  // the two rows bidirectionally. The current tree stays selected; the
242	  // updated anchor is reflected into the member store so the badge appears.
243	  createLinkedSubtree: async (memberId: string, name: string) => {
244	    const current = get().selectedTree;
245	    if (!current) throw new Error("No tree selected");
246	    const res = await TreeService.createMemberSubtree(
247	      current.id,
248	      memberId,
249	      name,
250	    );
251	    set((s) => ({ trees: [res.tree, ...s.trees] }));
252	    useMemberStore.setState((s) => ({
253	      members: s.members.map((m) =>
254	        m.id === memberId
255	          ? {
256	              ...m,
257	              linkedTreeId: res.anchor.linkedTreeId ?? null,
258	              linkedMemberId: res.anchor.linkedMemberId ?? null,
259	            }
260	          : m,
261	      ),
262	    }));
263	    return res.tree;
264	  },
265	
266	  // Tree-in-tree "link existing tree": resolves a bridge person against an
267	  // already-existing target tree — either an existing member the caller
268	  // asserts is the same person, or a fresh copy seeded into the target. The
269	  // current tree stays selected; the updated anchor is reflected into the
270	  // member store so the badge appears immediately.
271	  linkExistingTree: async (memberId, body) => {
272	    const current = get().selectedTree;
273	    if (!current) throw new Error("No tree selected");
274	    const res = await TreeService.linkMemberToTree(current.id, memberId, body);
275	    set((s) => ({
276	      trees: s.trees.some((t) => t.id === res.tree.id)
277	        ? s.trees
278	        : [res.tree, ...s.trees],
279	    }));
280	    useMemberStore.setState((s) => ({
281	      members: s.members.map((m) =>
282	        m.id === memberId
283	          ? {
284	              ...m,
285	              linkedTreeId: res.anchor.linkedTreeId ?? null,
286	              linkedMemberId: res.anchor.linkedMemberId ?? null,
287	            }
288	          : m,
289	      ),
290	    }));
291	    return res.tree;
292	  },
293	
294	  // Jump back to an ancestor in the breadcrumb, dropping everything below it.
295	  navigateToTreeStack: async (index: number) => {
296	    const entry = get().treeNavStack[index];
297	    if (!entry) return;
298	    set((s) => ({ treeNavStack: s.treeNavStack.slice(0, index) }));
299	    await get().connect({ id: entry.id, name: entry.name });
300	  },
301	
302	  renameTree: async (tree: Tree, name: string) => {
303	    const updated = await api.patch<Tree>(`/trees/${tree.id}`, { name });
304	    set((s) => ({
305	      trees: s.trees.map((t) => (t.id === tree.id ? updated : t)),
306	      selectedTree: s.selectedTree?.id === tree.id ? updated : s.selectedTree,
307	    }));
308	  },
309	
310	  updateTree: (tree: Tree) => {
311	    set((s) => ({
312	      trees: s.trees.map((t) => (t.id === tree.id ? tree : t)),
313	      selectedTree: s.selectedTree?.id === tree.id ? tree : s.selectedTree,
314	    }));
315	  },
316	
317	  deleteTree: async (tree: Tree) => {
318	    await api.del(`/trees/${tree.id}`);
319	    const wasSelected = get().selectedTree?.id === tree.id;
320	    set((s) => ({
321	      trees: s.trees.filter((t) => t.id !== tree.id),
322	    }));
323	    if (wasSelected) await get().disconnect();
324	  },
325	
326	  mergeTrees: async (
327	    name: string,
328	    sourceA: string,
329	    sourceB?: string,
330	    resolutions?: MergeResolution[],
331	  ) => {
332	    const { job_id } = await api.post<{ job_id: string }>("/trees/merge", {
333	      name,
334	      source_a: sourceA,
335	      source_b: sourceB ?? null,
336	      resolutions: resolutions ?? null,
337	    });
338	    const treeId = await useJobStore.getState().trackJob(job_id);
339	    const tree = await api.get<Tree>(`/trees/${treeId}`);
340	    await get().loadTrees();
341	    await get().selectTree(tree);
342	    return tree;
343	  },
344	
345	  extractSubtree: async (payload) => {
346	    const { job_id } = await TreeService.extractSubtree(payload);
347	    const treeId = await useJobStore.getState().trackJob(job_id);
348	    const tree = await api.get<Tree>(`/trees/${treeId}`);
349	    await get().loadTrees();
350	    await get().selectTree(tree);
351	    return tree;
352	  },
353	
354	  extractSubtreePreview: async (payload) => {
355	    return TreeService.previewSubtree(payload);
356	  },
357	
358	  fetchTreeMembers: async (treeId: string) => {
359	    const rows = await TreeService.getMembers(treeId);
360	    return (rows as MemberDB[]).map((r) => mapMemberFromDB(r));
361	  },
362	
363	  createVirtualView: async (name: string, sourceTreeIds: string[]) => {
364	    const view = await TreeService.createVirtualView(name, sourceTreeIds);
365	    set((s) => ({ virtualViews: [view, ...s.virtualViews] }));
366	    await get().selectTree(view);
367	    return view;
368	  },
369	
370	  renameVirtualView: async (view: Tree, name: string) => {
371	    const updated = await TreeService.updateVirtualView(view.id, { name });
372	    set((s) => ({
373	      virtualViews: s.virtualViews.map((v) => (v.id === view.id ? updated : v)),
374	      selectedTree: s.selectedTree?.id === view.id ? updated : s.selectedTree,
375	    }));
376	  },
377	
378	  updateVirtualViewSources: async (view: Tree, sourceTreeIds: string[]) => {
379	    const updated = await TreeService.updateVirtualView(view.id, {
380	      source_tree_ids: sourceTreeIds,
381	    });
382	    set((s) => ({
383	      virtualViews: s.virtualViews.map((v) => (v.id === view.id ? updated : v)),
384	      selectedTree: s.selectedTree?.id === view.id ? updated : s.selectedTree,
385	    }));
386	  },
387	
388	  deleteVirtualView: async (view: Tree) => {
389	    await TreeService.deleteVirtualView(view.id);
390	    const wasSelected = get().selectedTree?.id === view.id;
391	    set((s) => ({
392	      virtualViews: s.virtualViews.filter((v) => v.id !== view.id),
393	    }));
394	    if (wasSelected) {
395	      // Fall back to another tree (or remaining view) instead of leaving the
396	      // app in the "no database" state.
397	      const { trees, virtualViews } = get();
398	      const next = trees[0] ?? virtualViews[0];
399	      if (next) await get().selectTree(next);
400	      else await get().disconnect();
401	    }
402	  },
403	
404	  recomputeMatches: async (view: Tree) => {
405	    const result = await TreeService.recomputeVirtualViewMatches(view.id);
406	    const treeId = get().selectedTree?.id;
407	    if (treeId === view.id) {
408	      await useMemberStore.getState().refreshMembers(treeId);
409	      await get().refreshMetadata(treeId);
410	    }
411	    return result;
412	  },
413	
414	  selectTree: async (tree: Tree | undefined) => {
415	    treeRequestVersion += 1;
416	    // Picking a tree directly (e.g. from the database selector) resets the
417	    // tree-in-tree breadcrumb; only link-following keeps the ancestor chain.
418	    set({ treeNavStack: [] });
419	    if (!tree) {
420	      await get().disconnect();
421	      return;
422	    }
423	    set({ selectedTree: tree });
424	    await get().connect(tree);
425	  },
426	
427	  connect: async (tree: Tree) => {
428	    set({
429	      selectedTree: tree,
430	      isReady: false,
431	      metadata: {},
432	      relationTypes: [],
433	    });
434	
435	    // Switching directly between trees does not go through disconnect(). Clear
436	    // every content store here so deferred views do not retain their previous
437	    // tree's data or initialized state while they wait for their first visit.
438	    clearDataStores();
439	
440	    const virtual = isVirtualId(tree.id);
441	
442	    // Marks the tree/view as "opened" server-side and returns the latest
443	    // role + (for views) the resolved source list.
444	    try {
445	      const fresh = await api.get<Tree>(
446	        virtual ? `/virtual-views/${tree.id}` : `/trees/${tree.id}`,
447	      );
448	      // A later selection or disconnect supersedes this request. Do not let
449	      // its response restore a stale tree after the newer transition wins.
450	      if (!isActiveTree(tree.id)) return;
451	      set((s) => ({
452	        selectedTree: fresh,
453	        trees: virtual
454	          ? s.trees
455	          : s.trees.map((t) => (t.id === fresh.id ? fresh : t)),
456	        virtualViews: virtual
457	          ? s.virtualViews.map((v) => (v.id === fresh.id ? fresh : v))
458	          : s.virtualViews,
459	      }));
460	    } catch (error) {
461	      if (
462	        error instanceof ApiError &&
463	        (error.status === 403 || error.status === 404)
464	      ) {
465	        // Access is truly gone (revoked mid-session, or the tree/view was
466	        // deleted) — don't limp along with the stale tree object and an
467	        // empty canvas. Tear down only when this tree is still the active
468	        // one (a concurrent SSE-triggered loadTrees may have disconnected
469	        // already), but always re-throw so the caller (notification click,
470	        // tree selector) can surface the failure instead of resolving into
471	        // a silent empty state (#813).
472	        if (isActiveTree(tree.id)) {
473	          await get().disconnect();
474	          void get().loadTrees();
475	        }
476	        throw error;
477	      }
478	      if (!isActiveTree(tree.id)) return;
479	      // transient (network hiccup, 5xx) — proceed with what we already have.
480	    }
481	
482	    const loads = [
483	      get().refreshMetadata(tree.id),
484	      get().refreshRelationTypes(),
485	      useMemberStore.getState().refreshMembers(tree.id),
486	    ];
487	    await Promise.allSettled(loads);
488	    if (!isActiveTree(tree.id)) return;
489	
490	    // Virtual trees are read-only composites: auto-arrange the layout only
491	    // until the user saves an alignment overlay, then respect it.
492	    if (virtual && get().metadata.hasLayout !== true) {
493	      await useMemberStore.getState().updateLayout();
494	    }
495	
496	    // Freshly extracted (or seeded) trees: every member sits at (0, 0)
497	    // because they've never been arranged. Auto-arrange on first open,
498	    // same as virtual views, instead of showing a pile of stacked nodes.
499	    const freshRole = get().selectedTree?.role;
500	    const canWrite = freshRole === "owner" || freshRole === "editor";
501	    if (!virtual && canWrite) {
502	      const members = useMemberStore.getState().members;
503	      if (
504	        members.length >= 2 &&
505	        members.every((m) => m.position.x === 0 && m.position.y === 0)
506	      ) {
507	        await useMemberStore.getState().updateLayout();
508	      }
509	    }
510	    if (isActiveTree(tree.id)) set({ isReady: true });
511	  },
512	
513	  disconnect: async () => {
514	    treeRequestVersion += 1;
515	    set({
516	      selectedTree: undefined,
517	      isReady: false,
518	      metadata: {},
519	      relationTypes: [],
520	    });
521	    clearDataStores();
522	  },
523	
524	  disconnectPublicTree: async () => {
525	    await get().disconnect();
526	    // Public unlock tokens are in-memory only and must not survive leaving a
527	    // public view, including a later switch to an authenticated session.
528	    setPublicTreeToken(null);
529	  },
530	
531	  refreshMetadata: async (treeId = activeTreeId()) => {
532	    if (!treeId) return;
533	    const basePath = isVirtualId(treeId)
534	      ? `/virtual-views/${treeId}`
535	      : `/trees/${treeId}`;
536	    const metadata = await api.get<DatabaseMetaData>(`${basePath}/metadata`);
537	    if (!isActiveTree(treeId)) return;
538	    set({ metadata });
539	  },
540	
541	  refreshRelationTypes: async () => {
542	    const types = await TreeService.getRelationTypes();
543	    set({ relationTypes: types });
544	  },
545	}));
546	
547	/** Convenience accessor used by the data stores. */
548	export const activeTreeId = (): string | undefined =>
549	  useTreeStore.getState().selectedTree?.id;
550	
551	/** Stale-write guard for async loaders: true if `treeId` is still the active tree. */
552	export const isActiveTree = (treeId: string | undefined): boolean =>
553	  treeId !== undefined && activeTreeId() === treeId;
554	
555	export const resetTreeStoreForSession = () => {
556	  useTreeStore.setState({
557	    trees: [],
558	    virtualViews: [],
559	    selectedTree: undefined,
560	    metadata: {},
561	    relationTypes: [],
562	    isReady: false,
563	    treeNavStack: [],
564	  });
565	  clearDataStores();
566	};
