1	/**
2	 * Real-time tree-change notifications via Server-Sent Events.
3	 *
4	 * EventSource cannot include an Authorization header, so the access JWT is
5	 * exchanged for a one-purpose, short-lived SSE ticket. Reconnection uses
6	 * exponential backoff capped at 30 s.
7	 */
8	
9	import { toast } from "sonner";
10	import i18n from "@/i18n/i18n";
11	import { api } from "@/services/api";
12	import { useActivityStore } from "@/hooks/useActivityStore";
13	import { useAdminViewStore } from "@/hooks/useAdminViewStore";
14	import { useAuthStore } from "@/hooks/useAuthStore";
15	import { useJobStore } from "@/hooks/useJobStore";
16	import { useEventStore } from "@/hooks/useEventStore";
17	import { useFriendStore } from "@/hooks/useFriendStore";
18	import { useGalleryStore } from "@/hooks/useGalleryStore";
19	import { useMemberStore } from "@/hooks/useMemberStore";
20	import { useDocumentStore } from "@/hooks/useDocumentStore";
21	import { useNotificationStore } from "@/hooks/useNotificationStore";
22	import { useStorageStore } from "@/hooks/useStorageStore";
23	import { useStoryStore } from "@/hooks/useStoryStore";
24	import { refreshTaskStore } from "@/hooks/taskStoreRegistry";
25	import { usePresenceStore } from "@/hooks/usePresenceStore";
26	import { isActiveTree, useTreeStore } from "@/hooks/useTreeStore";
