30	const API_BASE = import.meta.env.VITE_API_BASE_URL || "/api";
31	
32	let source: EventSource | null = null;
33	let reconnectAttempts = 0;
34	let reconnectTimer: ReturnType<typeof setTimeout> | undefined;
35	let stopped = false;
36	let connecting = false;
37	let generation = 0;
38	
39	/** Open the SSE connection (idempotent if already open). */
40	export function startRealtime(): void {
41	  stopped = false;
42	  if (source !== null || connecting) return;
43	  void connect();
44	}
45	
46	async function connect(): Promise<void> {
47	  if (stopped || source !== null || connecting) return;
48	  const attempt = generation;
49	  connecting = true;
50	  let ticket: string;
51	  try {
52	    ({ ticket } = await api.post<{ ticket: string }>("/sse/ticket"));
53	  } catch {
54	    if (!stopped && attempt === generation) scheduleReconnect();
55	    return;
56	  } finally {
57	    if (attempt === generation) connecting = false;
58	  }
59	  if (stopped || attempt !== generation) return;
60	
61	  const url = `${API_BASE}/sse/events?ticket=${encodeURIComponent(ticket)}`;
62	  const eventSource = new EventSource(url);
63	  source = eventSource;
64	
65	  eventSource.onopen = () => {
66	    reconnectAttempts = 0;
67	  };
68	
69	  // The active tree can vanish from the user's list (access revoked, tree
70	  // deleted, ownership transferred). loadTrees() drops the stale selection —
71	  // detect that here and say why the canvas just switched/emptied, instead
72	  // of failing silently (#813/#814).
73	  const reload = async () => {
74	    const before = useTreeStore.getState().selectedTree;
75	    try {
76	      await useTreeStore.getState().loadTrees();
77	    } catch {
78	      // A replacement selection may fail to open; the next event retries.
79	    }
80	    const after = useTreeStore.getState().selectedTree;
81	    if (before && after?.id !== before.id) {
82	      toast.error(i18n.t("tree-view.access-revoked", { name: before.name }));
83	    }
84	  };
85	
86	  const onTreeListChanged = () => void reload();
87	
88	  eventSource.addEventListener("tree.ownership_changed", onTreeListChanged);
89	  eventSource.addEventListener("tree.access_changed", onTreeListChanged);
90	  eventSource.addEventListener("tree.deleted", onTreeListChanged);
91	
92	  eventSource.addEventListener("backup.completed", () => {
93	    useAdminViewStore.getState().bumpBackupTick();
94	  });
95	
96	  eventSource.addEventListener("purge.ran", () => {
97	    useAdminViewStore.getState().bumpPurgeTick();
98	  });
99	
100	  eventSource.addEventListener("session.invalidate", (e) => {
101	    const data = JSON.parse((e as MessageEvent).data) as { reason: string };
102	    const key =
103	      data.reason === "pending_deletion"
104	        ? "auth.session.invalidated-pending-deletion"
105	        : "auth.session.invalidated-deactivated";
106	    stopRealtime();
107	    useAuthStore.getState().logout();
