122	    document: (id) => void useDocumentStore.getState().refreshDocuments(id),
123	    gallery: (id) => void useGalleryStore.getState().refreshGalleryImages(id),
124	  };
125	  eventSource.addEventListener("tree.content_changed", (e) => {
126	    const data = JSON.parse((e as MessageEvent).data) as {
127	      tree_id: string;
128	      domain: string;
129	      actor_user_id?: string;
130	    };
131	    if (!isActiveTree(data.tree_id)) return;
132	    if (data.actor_user_id) {
133	      usePresenceStore.getState().markActivity(data.actor_user_id);
134	    }
135	    domainRefreshers[data.domain]?.(data.tree_id);
136	  });
137	
138	  eventSource.addEventListener("friend.request_received", (e) => {
139	    const data = JSON.parse((e as MessageEvent).data) as {
140	      requester_id: string;
141	      requester_username: string;
142	    };
143	    void useFriendStore.getState().loadIncoming();
144	    toast.info(
145	      i18n.t("auth.friends.new-request", { name: data.requester_username }),
146	    );
147	  });
148	
149	  eventSource.addEventListener("invitation.received", (e) => {
150	    const data = JSON.parse((e as MessageEvent).data) as {
151	      tree_id: string;
152	      tree_name: string;
153	    };
154	    void useTreeStore.getState().loadTrees();
155	    toast.info(
156	      i18n.t("dialog.share-tree.invitation-received", { name: data.tree_name }),
157	    );
158	  });
159	
160	  // Persistent notification inbox (#726). Toasts above stay as the immediate
161	  // nudge; this just keeps the bell's list/badge live. No toast here — it
162	  // would double up with the ones already fired above for the same events.
163	  eventSource.addEventListener("notification.created", (e) => {
164	    const data = JSON.parse((e as MessageEvent).data) as NotificationDB;
165	    useNotificationStore.getState().addFromEvent(data);
166	  });
167	
168	  eventSource.addEventListener("presence.updated", (e) => {
169	    const data = JSON.parse((e as MessageEvent).data) as {
170	      tree_id: string;
171	      users: PresenceUserDB[];
172	    };
173	    if (!isActiveTree(data.tree_id)) return;
174	    usePresenceStore.getState().setRoster(data.tree_id, data.users);
175	  });
176	
177	  eventSource.addEventListener("tree.layout_changed", (e) => {
178	    const data = JSON.parse((e as MessageEvent).data) as {
