187	  });
188	
189	  eventSource.addEventListener("job.progress", (e) => {
190	    const data = JSON.parse((e as MessageEvent).data) as {
191	      job_id: string;
192	      pct: number;
193	    };
194	    useJobStore.getState().onProgress(data.job_id, data.pct);
195	  });
196	
197	  eventSource.addEventListener("job.done", (e) => {
198	    const data = JSON.parse((e as MessageEvent).data) as {
199	      job_id: string;
200	      tree_id: string;
201	    };
202	    useJobStore.getState().onDone(data.job_id, data.tree_id);
203	  });
204	
205	  eventSource.addEventListener("job.failed", (e) => {
206	    const data = JSON.parse((e as MessageEvent).data) as {
207	      job_id: string;
208	      error: string;
209	    };
210	    useJobStore.getState().onFailed(data.job_id, data.error);
211	  });
212	
213	  eventSource.addEventListener("storage.warning", (e) => {
214	    const data = JSON.parse((e as MessageEvent).data) as {
215	      tree_id: string;
216	      used_bytes: number;
217	      quota_bytes: number;
218	    };
219	    if (!isActiveTree(data.tree_id)) return;
220	    void useStorageStore.getState().refreshStorageUsage(data.tree_id);
221	    toast.warning(i18n.t("storage-usage.quota-warning"));
222	  });
223	
224	  eventSource.onerror = () => {
225	    eventSource.close();
226	    if (source !== eventSource) return;
227	    source = null;
228	    if (stopped) return;
229	    scheduleReconnect();
230	  };
231	}
232	
233	function scheduleReconnect(): void {
234	  const delay = Math.min(1000 * 2 ** reconnectAttempts, 30_000);
235	  reconnectAttempts++;
236	  reconnectTimer = setTimeout(() => void connect(), delay);
237	}
238	
239	/** Close the SSE connection and cancel any pending reconnect. */
240	export function stopRealtime(): void {
241	  stopped = true;
242	  generation++;
243	  connecting = false;
244	  clearTimeout(reconnectTimer);
245	  source?.close();
246	  source = null;
247	  reconnectAttempts = 0;
248	}
