1	/**
2	 * Live-collaboration presence heartbeats.
3	 *
4	 * SSE is one-way, so a client announces itself by POSTing short heartbeats
5	 * (~30 s, plus immediately whenever its editing target changes). The server
6	 * replies with the full roster and also fans it out to everyone else as
7	 * `presence.updated`. A best-effort DELETE on leave keeps the roster tidy;
8	 * the server-side TTL is the backstop for a client that just vanishes.
9	 *
10	 * This module owns the timer and the "which tree / which member" state. React
11	 * drives it through `usePresence` — components never call it directly.
12	 */
13	
14	import { ApiError } from "@/services/api";
15	import { TreeService } from "@/services/TreeService";
16	import { usePresenceStore } from "@/hooks/usePresenceStore";
17	import { useTreeStore } from "@/hooks/useTreeStore";
18	
19	const HEARTBEAT_INTERVAL_MS = 30_000;
20	const HEARTBEAT_TIMEOUT_MS = 10_000;
21	
22	let currentTreeId: string | null = null;
23	let editingMemberId: string | null = null;
24	let timer: ReturnType<typeof setInterval> | undefined;
25	const inFlightTreeIds = new Set<string>();
26	const pendingTreeIds = new Set<string>();
27	const requestControllers = new Map<string, AbortController>();
28	
29	async function sendHeartbeat(): Promise<void> {
30	  const treeId = currentTreeId;
31	  if (!treeId) return;
32	  if (inFlightTreeIds.has(treeId)) {
33	    // Preserve the most recent edit target or tree selection rather than
34	    // silently waiting for the next 30-second interval.
35	    pendingTreeIds.add(treeId);
36	    return;
37	  }
38	
39	  inFlightTreeIds.add(treeId);
40	  pendingTreeIds.delete(treeId);
41	  const controller = new AbortController();
42	  requestControllers.set(treeId, controller);
43	  const timeout = setTimeout(() => controller.abort(), HEARTBEAT_TIMEOUT_MS);
44	
45	  try {
46	    const roster = await TreeService.sendPresence(
47	      treeId,
48	      editingMemberId,
49	      controller.signal,
50	    );
51	    // A tree switch may have landed while the request was in flight.
52	    if (treeId === currentTreeId) {
53	      usePresenceStore.getState().setRoster(roster.tree_id, roster.users);
54	    }
55	  } catch (err) {
56	    // 404: the feature was turned off at runtime. 403: access to the tree
57	    // was revoked mid-session. Both end this tree's presence session — stop
58	    // heartbeating and clear the roster so stale presence chips disappear
59	    // (#814).
60	    if (
61	      err instanceof ApiError &&
62	      (err.status === 404 || err.status === 403) &&
63	      treeId === currentTreeId
64	    ) {
65	      stopPresence();
66	      if (err.status === 403) {
67	        // Backstop in case the tree.access_changed SSE event was missed:
68	        // make the tree store notice the lost access right away.
69	        void useTreeStore
70	          .getState()
71	          .loadTrees()
72	          .catch(() => {
73	            // Transient failure — the next SSE event or heartbeat retries.
74	          });
75	      }
76	    }
77	    // Transient errors and aborted requests resolve on the next tick.
78	  } finally {
79	    clearTimeout(timeout);
80	    inFlightTreeIds.delete(treeId);
81	    if (requestControllers.get(treeId) === controller) {
82	      requestControllers.delete(treeId);
83	    }
84	    if (treeId === currentTreeId && pendingTreeIds.delete(treeId)) {
85	      void sendHeartbeat();
86	    }
87	  }
88	}
89	
90	/** Begin heartbeating for `treeId` (idempotent for the same tree). */
91	export function startPresence(treeId: string): void {
92	  if (currentTreeId === treeId) return;
93	  stopPresence();
94	  currentTreeId = treeId;
95	  editingMemberId = null;
96	  void sendHeartbeat();
97	  timer = setInterval(() => void sendHeartbeat(), HEARTBEAT_INTERVAL_MS);
98	}
99	
100	/** Stop heartbeating and drop out of the current tree's roster. */
101	export function stopPresence(): void {
102	  if (timer) {
103	    clearInterval(timer);
104	    timer = undefined;
105	  }
106	  const treeId = currentTreeId;
107	  currentTreeId = null;
108	  editingMemberId = null;
109	  pendingTreeIds.clear();
110	  if (treeId) requestControllers.get(treeId)?.abort();
111	  usePresenceStore.getState().clear();
112	  if (treeId) {
113	    void TreeService.leavePresence(treeId).catch(() => {
114	      // Best effort: the TTL cleans up if this never reaches the server.
115	    });
116	  }
117	}
118	
119	/** Update the member this client is editing (null = just viewing). */
120	export function setEditingMember(memberId: string | null): void {
121	  if (editingMemberId === memberId) return;
122	  editingMemberId = memberId;
123	  void sendHeartbeat();
124	}
