export const useTreeStore = create<DatabaseState>((set, get) => {
  // Land on the most recently used remaining tree/view (the API sorts by
  // last_opened — same rule as startup in App.tsx) instead of leaving a
  // blank canvas, when nothing is currently selected. Shared by loadTrees()
  // and connect()'s revoked-access recovery — both disconnect first (for an
  // immediate, deterministic UI reset), which clears `selectedTree` before
  // this runs, so it must read the *current* trees/virtualViews rather than
  // rely on the stale selection that triggered the disconnect. Best effort:
  // if the fallback tree fails to open, stay disconnected.
  const selectFallbackTree = async () => {
    if (get().selectedTree) return;
    const { trees, virtualViews } = get();
    const next = [...trees, ...virtualViews][0];
    if (next) {
      await get()
        .selectTree(next)
        .catch(() => {});
    }
  };

  return {
    trees: [],
    virtualViews: [],
    selectedTree: undefined,
    metadata: {},
    relationTypes: [],
    isReady: false,
    treeNavStack: [],

    loadTrees: async () => {
      const [trees, virtualViews] = await Promise.all([
        api.get<Tree[]>("/trees"),
        hasFeature("virtual_views")
          ? TreeService.listVirtualViews().catch(() => [] as Tree[])
          : Promise.resolve([] as Tree[]),
      ]);
      set({ trees, virtualViews });
      // Drop a stale selection that no longer exists / is no longer accessible.
      const selected = get().selectedTree;
      const allItems = [...trees, ...virtualViews];
      if (!selected) return;
      const freshSelected = allItems.find((t) => t.id === selected.id);
      if (freshSelected) {
        set({ selectedTree: freshSelected });
        return;
      }
      await get().disconnect();
      await selectFallbackTree();
    },

