87	    name: string,
88	    sourceA: string,
89	    sourceB?: string,
90	    resolutions?: MergeResolution[],
91	  ) => Promise<Tree>;
92	  extractSubtree: (payload: SubtreeExtractPayload) => Promise<Tree>;
93	  extractSubtreePreview: (
94	    payload: Omit<SubtreeExtractPayload, "name">,
95	  ) => Promise<SubtreeExtractPreview>;
96	  fetchTreeMembers: (treeId: string) => Promise<Member[]>;
97	  createVirtualView: (name: string, sourceTreeIds: string[]) => Promise<Tree>;
98	  renameVirtualView: (view: Tree, name: string) => Promise<void>;
99	  updateVirtualViewSources: (
100	    view: Tree,
101	    sourceTreeIds: string[],
102	  ) => Promise<void>;
103	  deleteVirtualView: (view: Tree) => Promise<void>;
104	  recomputeMatches: (
105	    view: Tree,
106	  ) => Promise<{ groupCount: number; mergedMemberCount: number }>;
107	  selectTree: (tree: Tree | undefined) => Promise<void>;
108	  connect: (tree: Tree) => Promise<void>;
109	  disconnect: () => Promise<void>;
110	  disconnectPublicTree: () => Promise<void>;
111	  refreshMetadata: (treeId?: string) => Promise<void>;
112	  refreshRelationTypes: () => Promise<void>;
113	}
114	
115	const clearDataStores = () => {
116	  useMemberStore.getState().clear();
117	  useGalleryStore.getState().clear();
118	  useEventStore.getState().clear();
119	  useStoryStore.getState().clear();
120	  clearTaskStore();
121	  useDocumentStore.getState().clear();
122	  useActivityStore.getState().clear();
123	  useStatisticsStore.getState().clear();
124	  useQualityReportStore.getState().clear();
125	  useStorageStore.getState().clear();
126	};
127	
128	export const useTreeStore = create<DatabaseState>((set, get) => {
129	  // Land on the most recently used remaining tree/view (the API sorts by
130	  // last_opened — same rule as startup in App.tsx) instead of leaving a
131	  // blank canvas, when nothing is currently selected. Shared by loadTrees()
132	  // and connect()'s revoked-access recovery — both disconnect first (for an
133	  // immediate, deterministic UI reset), which clears `selectedTree` before
134	  // this runs, so it must read the *current* trees/virtualViews rather than
135	  // rely on the stale selection that triggered the disconnect. Best effort:
136	  // if the fallback tree fails to open, stay disconnected.
137	  const selectFallbackTree = async () => {
138	    if (get().selectedTree) return;
139	    const { trees, virtualViews } = get();
140	    const next = [...trees, ...virtualViews][0];
141	    if (next) {
142	      await get()
143	        .selectTree(next)
144	        .catch(() => {});
145	    }
146	  };
147	
148	  return {
149	    trees: [],
150	    virtualViews: [],
151	    selectedTree: undefined,
152	    metadata: {},
153	    relationTypes: [],
154	    isReady: false,
155	    treeNavStack: [],
156	
157	    loadTrees: async () => {
158	      const [trees, virtualViews] = await Promise.all([
159	        api.get<Tree[]>("/trees"),
160	        hasFeature("virtual_views")
161	          ? TreeService.listVirtualViews().catch(() => [] as Tree[])
162	          : Promise.resolve([] as Tree[]),
163	      ]);
164	      set({ trees, virtualViews });
165	      // Drop a stale selection that no longer exists / is no longer accessible.
166	      const selected = get().selectedTree;
167	      const allItems = [...trees, ...virtualViews];
168	      if (!selected) return;
169	      const freshSelected = allItems.find((t) => t.id === selected.id);
170	      if (freshSelected) {
171	        set({ selectedTree: freshSelected });
172	        return;
173	      }
174	      await get().disconnect();
175	      await selectFallbackTree();
176	    },
177	
178	    // Resolve a tree before selecting it. This keeps link routing, including
179	    // public-tree links that are absent from a user's normal tree list, inside
180	    // the tree domain rather than making view components call the API directly.
181	    openTreeById: async (treeId: string) => {
182	      const requestVersion = ++treeRequestVersion;
183	      const tree = await api.get<Tree>(`/trees/${treeId}`);
184	      if (requestVersion !== treeRequestVersion) return tree;
185	      await get().selectTree(tree);
186	      return tree;
187	    },
188	
189	    openTreeAndLocateMember: async (treeId: string, memberId: string) => {
190	      const tree = await get().openTreeById(treeId);
191	      if (!isActiveTree(tree.id)) return;
192	      useMemberSheetStore.getState().setOpenSheet(tree.id, {
193	        memberId,
194	        tab: "identity",
195	        mode: "view",
196	      });
197	      // Set after the tree transition: connect() clears the member store, and
198	      // the canvas consumes this once the selected member has finished loading.
199	      useMemberStore.getState().setPendingLocateMemberId(memberId);
200	    },
201	
202	    unlockPublicTree: async (treeId: string, password: string) => {
203	      const { token } = await TreeSharingService.unlockPublicTree(
204	        treeId,
205	        password,
206	      );
207	      setPublicTreeToken(token);
208	      return get().openTreeById(treeId);
209	    },
210	
211	    createTree: async (name: string, options?: { select?: boolean }) => {
212	      const tree = await api.post<Tree>("/trees", { name });
213	      set((s) => ({ trees: [tree, ...s.trees] }));
214	      // `select: false` lets callers create a tree without switching to it — used
215	      // by the tree-in-tree "create & link" action so the current edit context is
216	      // preserved.
217	      if (options?.select !== false) {
218	        await get().selectTree(tree);
219	      }
220	      return tree;
221	    },
222	
223	    // Follow a member→tree link: remember where we came from (breadcrumb), verify
224	    // the target is accessible, then switch to it. Throws if the linked tree is
225	    // missing or the user has no access, so callers can surface a message.
226	    // When the link carries a counterpart member (the bridge person's row in the
227	    // target tree), the canvas centers on it after the switch.
228	    openLinkedTree: async (treeId: string, focusMemberId?: string | null) => {
229	      const current = get().selectedTree;
230	      if (!current || current.id === treeId) return;
231	      const target = await api.get<Tree>(`/trees/${treeId}`);
232	      // Following a back-link to where we just came from behaves like "back":
233	      // pop the breadcrumb instead of growing it (A → B → A stays two levels).
234	      const stack = get().treeNavStack;
235	      const last = stack[stack.length - 1];
236	      if (last && last.id === treeId) {
237	        set({ treeNavStack: stack.slice(0, -1) });
238	      } else {
239	        set({
240	          treeNavStack: [...stack, { id: current.id, name: current.name }],
241	        });
242	      }
243	      await get().connect(target);
244	      if (focusMemberId) {
245	        // Set after connect: the tree switch clears the member store, and the
246	        // canvas consumes this once the counterpart is present in `members`.
247	        useMemberStore.getState().setPendingLocateMemberId(focusMemberId);
248	      }
249	    },
250	
251	    // Tree-in-tree "create & link": one atomic backend call creates the new
252	    // tree, seeds it with a copy of the member (the bridge person) and links
253	    // the two rows bidirectionally. The current tree stays selected; the
254	    // updated anchor is reflected into the member store so the badge appears.
255	    createLinkedSubtree: async (memberId: string, name: string) => {
256	      const current = get().selectedTree;
257	      if (!current) throw new Error("No tree selected");
258	      const res = await TreeService.createMemberSubtree(
259	        current.id,
260	        memberId,
261	        name,
262	      );
263	      set((s) => ({ trees: [res.tree, ...s.trees] }));
264	      useMemberStore.setState((s) => ({
265	        members: s.members.map((m) =>
266	          m.id === memberId
267	            ? {
268	                ...m,
269	                linkedTreeId: res.anchor.linkedTreeId ?? null,
270	                linkedMemberId: res.anchor.linkedMemberId ?? null,
271	              }
272	            : m,
273	        ),
274	      }));
275	      return res.tree;
276	    },
277	
278	    // Tree-in-tree "link existing tree": resolves a bridge person against an
279	    // already-existing target tree — either an existing member the caller
280	    // asserts is the same person, or a fresh copy seeded into the target. The
281	    // current tree stays selected; the updated anchor is reflected into the
282	    // member store so the badge appears immediately.
283	    linkExistingTree: async (memberId, body) => {
284	      const current = get().selectedTree;
285	      if (!current) throw new Error("No tree selected");
286	      const res = await TreeService.linkMemberToTree(
287	        current.id,
288	        memberId,
289	        body,
290	      );
291	      set((s) => ({
292	        trees: s.trees.some((t) => t.id === res.tree.id)
293	          ? s.trees
294	          : [res.tree, ...s.trees],
295	      }));
296	      useMemberStore.setState((s) => ({
297	        members: s.members.map((m) =>
298	          m.id === memberId
299	            ? {
300	                ...m,
301	                linkedTreeId: res.anchor.linkedTreeId ?? null,
302	                linkedMemberId: res.anchor.linkedMemberId ?? null,
303	              }
304	            : m,
305	        ),
306	      }));
307	      return res.tree;
308	    },
309	
310	    // Jump back to an ancestor in the breadcrumb, dropping everything below it.
311	    navigateToTreeStack: async (index: number) => {
312	      const entry = get().treeNavStack[index];
313	      if (!entry) return;
314	      set((s) => ({ treeNavStack: s.treeNavStack.slice(0, index) }));
315	      await get().connect({ id: entry.id, name: entry.name });
316	    },
317	
318	    renameTree: async (tree: Tree, name: string) => {
319	      const updated = await api.patch<Tree>(`/trees/${tree.id}`, { name });
320	      set((s) => ({
321	        trees: s.trees.map((t) => (t.id === tree.id ? updated : t)),
322	        selectedTree: s.selectedTree?.id === tree.id ? updated : s.selectedTree,
323	      }));
324	    },
325	
326	    updateTree: (tree: Tree) => {
327	      set((s) => ({
328	        trees: s.trees.map((t) => (t.id === tree.id ? tree : t)),
329	        selectedTree: s.selectedTree?.id === tree.id ? tree : s.selectedTree,
330	      }));
331	    },
332	
333	    deleteTree: async (tree: Tree) => {
334	      await api.del(`/trees/${tree.id}`);
335	      const wasSelected = get().selectedTree?.id === tree.id;
336	      set((s) => ({
337	        trees: s.trees.filter((t) => t.id !== tree.id),
338	      }));
339	      if (wasSelected) await get().disconnect();
340	    },
341	
342	    mergeTrees: async (
343	      name: string,
344	      sourceA: string,
345	      sourceB?: string,
346	      resolutions?: MergeResolution[],
347	    ) => {
348	      const { job_id } = await api.post<{ job_id: string }>("/trees/merge", {
349	        name,
350	        source_a: sourceA,
351	        source_b: sourceB ?? null,
352	        resolutions: resolutions ?? null,
353	      });
354	      const treeId = await useJobStore.getState().trackJob(job_id);
355	      const tree = await api.get<Tree>(`/trees/${treeId}`);
356	      await get().loadTrees();
357	      await get().selectTree(tree);
358	      return tree;
359	    },
360	
361	    extractSubtree: async (payload) => {
362	      const { job_id } = await TreeService.extractSubtree(payload);
363	      const treeId = await useJobStore.getState().trackJob(job_id);
364	      const tree = await api.get<Tree>(`/trees/${treeId}`);
365	      await get().loadTrees();
366	      await get().selectTree(tree);
367	      return tree;
368	    },
369	
370	    extractSubtreePreview: async (payload) => {
371	      return TreeService.previewSubtree(payload);
372	    },
373	
374	    fetchTreeMembers: async (treeId: string) => {
375	      const rows = await TreeService.getMembers(treeId);
376	      return (rows as MemberDB[]).map((r) => mapMemberFromDB(r));
377	    },
378	
379	    createVirtualView: async (name: string, sourceTreeIds: string[]) => {
380	      const view = await TreeService.createVirtualView(name, sourceTreeIds);
381	      set((s) => ({ virtualViews: [view, ...s.virtualViews] }));
382	      await get().selectTree(view);
383	      return view;
384	    },
385	
386	    renameVirtualView: async (view: Tree, name: string) => {
387	      const updated = await TreeService.updateVirtualView(view.id, { name });
388	      set((s) => ({
389	        virtualViews: s.virtualViews.map((v) =>
390	          v.id === view.id ? updated : v,
391	        ),
392	        selectedTree: s.selectedTree?.id === view.id ? updated : s.selectedTree,
393	      }));
394	    },
395	
396	    updateVirtualViewSources: async (view: Tree, sourceTreeIds: string[]) => {
397	      const updated = await TreeService.updateVirtualView(view.id, {
398	        source_tree_ids: sourceTreeIds,
399	      });
400	      set((s) => ({
401	        virtualViews: s.virtualViews.map((v) =>
402	          v.id === view.id ? updated : v,
403	        ),
404	        selectedTree: s.selectedTree?.id === view.id ? updated : s.selectedTree,
405	      }));
406	    },
407	
408	    deleteVirtualView: async (view: Tree) => {
409	      await TreeService.deleteVirtualView(view.id);
410	      const wasSelected = get().selectedTree?.id === view.id;
411	      set((s) => ({
412	        virtualViews: s.virtualViews.filter((v) => v.id !== view.id),
413	      }));
414	      if (wasSelected) {
415	        // Fall back to another tree (or remaining view) instead of leaving the
416	        // app in the "no database" state.
417	        const { trees, virtualViews } = get();
418	        const next = trees[0] ?? virtualViews[0];
419	        if (next) await get().selectTree(next);
420	        else await get().disconnect();
421	      }
422	    },
423	
424	    recomputeMatches: async (view: Tree) => {
425	      const result = await TreeService.recomputeVirtualViewMatches(view.id);
426	      const treeId = get().selectedTree?.id;
427	      if (treeId === view.id) {
428	        await useMemberStore.getState().refreshMembers(treeId);
429	        await get().refreshMetadata(treeId);
430	      }
431	      return result;
432	    },
433	
434	    selectTree: async (tree: Tree | undefined) => {
435	      treeRequestVersion += 1;
436	      // Picking a tree directly (e.g. from the database selector) resets the
437	      // tree-in-tree breadcrumb; only link-following keeps the ancestor chain.
438	      set({ treeNavStack: [] });
439	      if (!tree) {
440	        await get().disconnect();
441	        return;
442	      }
443	      set({ selectedTree: tree });
444	      await get().connect(tree);
445	    },
446	
447	    connect: async (tree: Tree) => {
448	      set({
449	        selectedTree: tree,
450	        isReady: false,
451	        metadata: {},
452	        relationTypes: [],
453	      });
454	
455	      // Switching directly between trees does not go through disconnect(). Clear
456	      // every content store here so deferred views do not retain their previous
457	      // tree's data or initialized state while they wait for their first visit.
458	      clearDataStores();
459	
460	      const virtual = isVirtualId(tree.id);
461	
462	      // Marks the tree/view as "opened" server-side and returns the latest
463	      // role + (for views) the resolved source list.
464	      try {
465	        const fresh = await api.get<Tree>(
466	          virtual ? `/virtual-views/${tree.id}` : `/trees/${tree.id}`,
467	        );
468	        // A later selection or disconnect supersedes this request. Do not let
469	        // its response restore a stale tree after the newer transition wins.
470	        if (!isActiveTree(tree.id)) return;
471	        set((s) => ({
472	          selectedTree: fresh,
473	          trees: virtual
474	            ? s.trees
475	            : s.trees.map((t) => (t.id === fresh.id ? fresh : t)),
476	          virtualViews: virtual
477	            ? s.virtualViews.map((v) => (v.id === fresh.id ? fresh : v))
478	            : s.virtualViews,
479	        }));
480	      } catch (error) {
481	        if (
482	          error instanceof ApiError &&
483	          (error.status === 403 || error.status === 404)
484	        ) {
485	          // Access is truly gone (revoked mid-session, or the tree/view was
486	          // deleted) — don't limp along with the stale tree object and an
487	          // empty canvas. Tear down only when this tree is still the active
488	          // one (a concurrent SSE-triggered loadTrees may have disconnected
489	          // already), but always re-throw so the caller (notification click,
490	          // tree selector) can surface the failure instead of resolving into
491	          // a silent empty state (#813).
492	          if (isActiveTree(tree.id)) {
493	            await get().disconnect();
494	            // disconnect() already cleared `selectedTree`, so loadTrees()'s own
495	            // "was something selected before this refresh?" check can no
496	            // longer see it — refresh the lists here, then land on a
497	            // remaining tree ourselves instead of leaving a blank canvas.
498	            // Fire-and-forget: the caller doesn't need to wait on this to see
499	            // the rejection below.
500	            void get()
501	              .loadTrees()
502	              .then(() => selectFallbackTree())
503	              .catch(() => {
504	                // Transient failure refreshing the list — the next SSE event
505	                // or heartbeat retries.
506	              });
507	          }
508	          throw error;
509	        }
510	        if (!isActiveTree(tree.id)) return;
511	        // transient (network hiccup, 5xx) — proceed with what we already have.
512	      }
513	
514	      const loads = [
515	        get().refreshMetadata(tree.id),
516	        get().refreshRelationTypes(),
517	        useMemberStore.getState().refreshMembers(tree.id),
518	      ];
519	      await Promise.allSettled(loads);
520	      if (!isActiveTree(tree.id)) return;
521	
522	      // Virtual trees are read-only composites: auto-arrange the layout only
523	      // until the user saves an alignment overlay, then respect it.
524	      if (virtual && get().metadata.hasLayout !== true) {
525	        await useMemberStore.getState().updateLayout();
526	      }
527	
528	      // Freshly extracted (or seeded) trees: every member sits at (0, 0)
529	      // because they've never been arranged. Auto-arrange on first open,
530	      // same as virtual views, instead of showing a pile of stacked nodes.
531	      const freshRole = get().selectedTree?.role;
532	      const canWrite = freshRole === "owner" || freshRole === "editor";
533	      if (!virtual && canWrite) {
534	        const members = useMemberStore.getState().members;
535	        if (
536	          members.length >= 2 &&
537	          members.every((m) => m.position.x === 0 && m.position.y === 0)
538	        ) {
539	          await useMemberStore.getState().updateLayout();
540	        }
541	      }
542	      if (isActiveTree(tree.id)) set({ isReady: true });
543	    },
544	
545	    disconnect: async () => {
546	      treeRequestVersion += 1;
547	      set({
548	        selectedTree: undefined,
549	        isReady: false,
550	        metadata: {},
551	        relationTypes: [],
552	      });
553	      clearDataStores();
554	    },
555	
556	    disconnectPublicTree: async () => {
557	      await get().disconnect();
558	      // Public unlock tokens are in-memory only and must not survive leaving a
559	      // public view, including a later switch to an authenticated session.
560	      setPublicTreeToken(null);
561	    },
562	
563	    refreshMetadata: async (treeId = activeTreeId()) => {
564	      if (!treeId) return;
565	      const basePath = isVirtualId(treeId)
566	        ? `/virtual-views/${treeId}`
567	        : `/trees/${treeId}`;
568	      const metadata = await api.get<DatabaseMetaData>(`${basePath}/metadata`);
569	      if (!isActiveTree(treeId)) return;
570	      set({ metadata });
571	    },
572	
573	    refreshRelationTypes: async () => {
574	      const types = await TreeService.getRelationTypes();
575	      set({ relationTypes: types });
576	    },
577	  };
578	});
579	
580	/** Convenience accessor used by the data stores. */
581	export const activeTreeId = (): string | undefined =>
582	  useTreeStore.getState().selectedTree?.id;
583	
584	/** Stale-write guard for async loaders: true if `treeId` is still the active tree. */
585	export const isActiveTree = (treeId: string | undefined): boolean =>
586	  treeId !== undefined && activeTreeId() === treeId;
587	
588	export const resetTreeStoreForSession = () => {
589	  useTreeStore.setState({
590	    trees: [],
591	    virtualViews: [],
592	    selectedTree: undefined,
593	    metadata: {},
594	    relationTypes: [],
595	    isReady: false,
596	    treeNavStack: [],
597	  });
598	  clearDataStores();
599	};
